def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    foreground = max((v for v in counts if v != background), key=lambda v: counts[v])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == foreground]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    out = [row[:] for row in grid]

    # Complete the upper and lower frame edges between the extreme columns.
    for r in (r0, r1):
        for c in range(c0, c1 + 1):
            if grid[r][c] == background:
                out[r][c] = 2
    # Complete the two side edges between the extreme rows.
    for r in range(r0, r1 + 1):
        for c in (c0, c1):
            if grid[r][c] == background:
                out[r][c] = 2

    # Also bridge zero/background gaps along inner rows that contain multiple marks,
    # provided the row has a separated marker at the right side (the frame's guide).
    for r in range(r0, r1 + 1):
        marks = [c for c in range(c0, c1 + 1) if grid[r][c] == foreground]
        if len(marks) >= 2 and c1 in marks:
            for c in range(c0, c1 + 1):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out
